// TeamsOverview — the grid-on-canvas of team summary cards (click to enter). Promoted from harvested
// (it was already complete and tested) into base-studio-code, refactored to use the real Box/Row/Text/
// IconBox/Skeleton primitives instead of local raw-div redeclarations. The absolute-position grid
// layout, loading skeleton grid, and error card are unchanged from the vendored source.
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { IconBox } from "@/shared/ui/data/IconBox";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";

function teamsGrid(n: number, cellW = 260, cellH = 130, gap = 28, perRow = 4): { x: number; y: number; w: number; h: number }[] {
  const cells: { x: number; y: number; w: number; h: number }[] = [];
  for (let i = 0; i < n; i++) {
    const col = i % perRow, row = Math.floor(i / perRow);
    cells.push({ x: col * (cellW + gap), y: row * (cellH + gap), w: cellW, h: cellH });
  }
  return cells;
}

export interface TeamPositionSummary { kind: "agent" | "resource" | "external" }
export interface TeamSummary {
  id: string;
  name: string;
  blurb?: string;
  positions: TeamPositionSummary[];
}
function teamStats(team: TeamSummary): { agents: number; positions: number; externals: number } {
  return {
    agents: team.positions.filter((p) => p.kind === "agent").length,
    positions: team.positions.length,
    externals: team.positions.filter((p) => p.kind === "external").length,
  };
}

const DEMO_TEAMS: TeamSummary[] = [
  { id: "t1", name: "Platform", blurb: "Owns the shared design system and the build pipeline.", positions: [{ kind: "agent" }, { kind: "agent" }, { kind: "resource" }] },
  { id: "t2", name: "Growth", blurb: "Runs experiments across onboarding and activation.", positions: [{ kind: "agent" }, { kind: "external" }] },
];

export function TeamsOverview({ teams = DEMO_TEAMS, onEnter = () => {}, loading = false, error }: { teams?: TeamSummary[]; onEnter?: (teamId: string) => void; loading?: boolean; error?: string | boolean }) {
  if (error) {
    const b = teamsGrid(1)[0];
    const msg = typeof error === "string" ? error : "Couldn't load teams.";
    return (
      <div style={{ position: "absolute", left: b.x, top: b.y, width: Math.max(b.w * 2 + 28, 400), height: b.h }}>
        <Box style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "13px 15px", display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 14, background: "var(--bg-elev)", border: "1px dashed var(--danger)" }}>
          <Text size={12} tone="muted" style={{ color: "var(--danger)" }}>{msg}</Text>
        </Box>
      </div>
    );
  }

  if (loading) {
    const cells = teamsGrid(teams.length || 2);
    return (
      <>
        {cells.map((b, i) => (
          <div key={i} style={{ position: "absolute", left: b.x, top: b.y, width: b.w, height: b.h }}>
            <Box style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "13px 15px", display: "flex", flexDirection: "column", gap: 8, borderRadius: 14, background: "var(--bg-elev)", border: "1px solid var(--border)" }}>
              <Row gap={10} align="center"><Skeleton w={26} h={26} radius={8} /><Skeleton w="55%" h={13} /></Row>
              <Skeleton h={11} style={{ marginTop: 2 }} />
              <Skeleton w="70%" h={11} />
              <Box style={{ flex: 1 }} />
              <Skeleton w="50%" h={10} />
            </Box>
          </div>
        ))}
      </>
    );
  }

  const cells = teamsGrid(teams.length);

  return (
    <>
      {teams.map((team, i) => {
        const b = cells[i];
        const s = teamStats(team);
        return (
          <div key={team.id} onPointerDown={(e) => e.stopPropagation()} onClick={() => onEnter(team.id)}
            style={{ position: "absolute", left: b.x, top: b.y, width: b.w, height: b.h, cursor: "pointer" }}>
            <Box className="teams-card" style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "13px 15px",
              display: "flex", flexDirection: "column", gap: 8, borderRadius: 14, background: "var(--bg-elev)",
              border: "1px solid var(--border)", boxShadow: "0 3px 12px rgba(0,0,0,.3)" }}>
              <Row gap={10} align="center">
                <IconBox size={26} radius={8} fontSize={13} color="var(--accent)" background="color-mix(in oklch, var(--accent) 14%, transparent)">{"◆"}</IconBox>
                <Text as="span" weight={600} size={14.5} style={{ flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{team.name}</Text>
              </Row>
              {team.blurb && <Text as="div" size={11.5} tone="muted" style={{ lineHeight: 1.4, overflow: "hidden", display: "-webkit-box", WebkitLineClamp: 4, WebkitBoxOrient: "vertical" }}>{team.blurb}</Text>}
              <Box style={{ flex: 1 }} />
              <Row gap={12} align="center">
                <Text as="span" mono size={10} tone="dim">{"◆"} {s.agents} agent{s.agents === 1 ? "" : "s"}</Text>
                <Text as="span" mono size={10} tone="dim">{"·"} {s.positions} position{s.positions === 1 ? "" : "s"}</Text>
                {s.externals > 0 && <Text as="span" mono size={10} tone="dim">{"·"} {s.externals} ext</Text>}
              </Row>
            </Box>
          </div>
        );
      })}
    </>
  );
}
